'use client';
import {lazy,useEffect,useRef,useState} from 'react';

import type {Membership} from '@/lib/pilot';


import {Download,Printer} from 'lucide-react';

import {hotelRpc,type RoomType,type Room} from '@/lib/pilot';

import {afterDays} from '@/lib/rates';

import {downloadReport,reportMoney,reportUsd,type ReportCell} from '@/lib/report-export';

import {operationalRows,reportKinds,reportDefinitions,type ReportKind,type OperationalReport} from '@/lib/operational-reports';

type Props={actor?:string;membership?:Membership;tenant:string;property:string;businessDate:string;types:RoomType[];rooms:Room[]};
function reportCellText(cell:ReportCell){return cell==null?'—':typeof cell==='object'?cell.value:String(cell)}

const PickupScheduleStatus=lazy(()=>import('@/components/pickup-schedule-status').then(module=>({default:module.PickupScheduleStatus})));
const PickupReport=lazy(()=>import('@/components/pickup-report').then(module=>({default:module.PickupReport})));
const HistoricalPerformance=lazy(()=>import('@/components/historical-performance').then(module=>({default:module.HistoricalPerformance})));
const PaymentTransferAction=lazy(()=>import('@/components/payment-transfer-action').then(module=>({default:module.PaymentTransferAction})));
const ActiveCashiers=lazy(()=>import('@/components/active-cashiers').then(module=>({default:module.ActiveCashiers})));
const InvoiceAgingReport=lazy(()=>import('@/components/invoice-aging-report').then(module=>({default:module.InvoiceAgingReport})));
const CashierClosingReport=lazy(()=>import('@/components/cashier-closing-report').then(module=>({default:module.CashierClosingReport})));
const PaymentAccountingWorkspace=lazy(()=>import('@/components/payment-accounting-workspace').then(module=>({default:module.PaymentAccountingWorkspace})));
const PaymentAccountingAction=lazy(()=>import('@/components/payment-accounting-action').then(module=>({default:module.PaymentAccountingAction})));
const GuestBalanceRegister=lazy(()=>import('@/components/guest-balance-register').then(module=>({default:module.GuestBalanceRegister})));
const NightlyBatchAction=lazy(()=>import('@/components/nightly-batch-action').then(module=>({default:module.NightlyBatchAction})));
const AccountingAdjustments=lazy(()=>import('@/components/accounting-adjustments').then(module=>({default:module.AccountingAdjustments})));
const AccountingAdjustmentAction=lazy(()=>import('@/components/accounting-adjustment-action').then(module=>({default:module.AccountingAdjustmentAction})));
const AccountingSetupAction=lazy(()=>import('@/components/accounting-setup-action').then(module=>({default:module.AccountingSetupAction})));
const AccountingPeriodCloseAction=lazy(()=>import('@/components/accounting-period-close-action').then(module=>({default:module.AccountingPeriodCloseAction})));
const AccountingPostingAction=lazy(()=>import('@/components/accounting-posting-action').then(module=>({default:module.AccountingPostingAction})));
const AccountingSetupView=lazy(()=>import('@/components/accounting-setup').then(module=>({default:module.AccountingSetupView})));
const AccountingReports=lazy(()=>import('@/components/accounting-reports').then(module=>({default:module.AccountingReports})));
const NoShowReport=lazy(()=>import('@/components/no-show-report').then(module=>({default:module.NoShowReport})));
const FrontOfficeStatistics=lazy(()=>import('@/components/front-office-statistics').then(module=>({default:module.FrontOfficeStatistics})));

export function ReportsPanel(props:Props){

 const [group,setGroup]=useState('operations');

 const canReadAccounting=props.membership?.role==='owner'||props.membership?.role==='manager';

 return <><label className="field pilot-report-kind">Report group<select value={group} onChange={e=>setGroup(e.target.value)}><option value="operations">Operations &amp; bookings</option><option value="active_cashiers">Active cashier drawers</option><option value="invoice_aging">Invoice aging</option><option value="cashier_closings">Cashier closings</option><option value="no_shows">No-show arrivals</option>{canReadAccounting&&<><option value="front_office_statistics">Front-office statistics</option><option value="pickup">Booking pickup · preview</option><option value="historical_performance">Historical overnight performance</option><option value="payment_accounting">Accounting / payments</option><option value="guest_balances">Current guest balances</option><option value="accounting">Accounting · trial balance</option><option value="accounting_adjustments">Accounting · manual adjustments</option><option value="accounting_setup">Accounting · setup</option></>}<option value="accounting_recovery">Accounting request recovery</option></select></label>{group==='front_office_statistics'?(canReadAccounting&&props.membership?<FrontOfficeStatistics key={props.tenant+'/'+props.property} membership={props.membership} businessDate={props.businessDate}/>:<p>Front-office statistics are available to owners and managers.</p>):group==='pickup'?(canReadAccounting?<>{props.membership?.role==='owner'&&<PickupScheduleStatus tenant={props.tenant} property={props.property}/>}<PickupReport key={props.tenant+'/'+props.property} tenant={props.tenant} property={props.property} types={props.types} actor={props.actor} businessDate={props.businessDate} timeZone={props.membership?.time_zone}/></>:<p>Pickup reports are available to owners and managers.</p>):group==='active_cashiers'?(props.membership?<ActiveCashiers membership={props.membership}/>:<p>Select a signed-in property first.</p>):group==='cashier_closings'?(props.membership?<CashierClosingReport membership={props.membership} businessDate={props.businessDate}/>:<p>Select a signed-in property first.</p>):group==='historical_performance'?(canReadAccounting&&props.membership?<HistoricalPerformance key={props.tenant+'/'+props.property} membership={props.membership} businessDate={props.businessDate}/>:<p>Historical performance is available to owners and managers.</p>):group==='payment_accounting'?(canReadAccounting&&props.membership?<PaymentAccountingWorkspace membership={props.membership} businessDate={props.businessDate}/>:<p>Payment accounting is available to owners and managers.</p>):group==='guest_balances'?(canReadAccounting&&props.membership?<GuestBalanceRegister key={props.tenant+'/'+props.property} membership={props.membership} businessDate={props.businessDate}/>:<p>Guest balances are available to owners and managers.</p>):group==='invoice_aging'?(canReadAccounting&&props.membership?<InvoiceAgingReport membership={props.membership} businessDate={props.businessDate}/>:<p>Invoice aging is available to owners and managers.</p>):group==='accounting_recovery'?(props.membership?<><PaymentTransferAction key={'transfer/'+props.tenant+'/'+props.property} membership={props.membership} preview={null}/><PaymentAccountingAction key={'payment/'+props.tenant+'/'+props.property} membership={props.membership} preview={null}/><NightlyBatchAction key={'batch/'+props.tenant+'/'+props.property} membership={props.membership} review={null}/><AccountingAdjustmentAction key={'adjustment/'+props.tenant+'/'+props.property} membership={props.membership} preview={null}/><AccountingPostingAction key={props.tenant+'/'+props.property} membership={props.membership} preview={null}/><AccountingPeriodCloseAction key={'close/'+props.tenant+'/'+props.property} membership={props.membership} preview={null}/><AccountingSetupAction key={'setup/'+props.tenant+'/'+props.property} membership={props.membership} preview={null}/></>:<p>Select a signed-in property first.</p>):group==='accounting_adjustments'?(canReadAccounting&&props.membership?<AccountingAdjustments key={props.tenant+'/'+props.property} membership={props.membership} businessDate={props.businessDate}/>:<p>Accounting adjustments are available to owners and managers.</p>):group==='accounting_setup'?(canReadAccounting&&props.membership?<AccountingSetupView key={props.tenant+'/'+props.property} membership={props.membership}/>:<p>Accounting setup is available to owners and managers.</p>):group==='accounting'?(canReadAccounting&&props.membership?<AccountingReports key={props.tenant+'/'+props.property} membership={props.membership} businessDate={props.businessDate}/>:<p>Accounting reports are available to owners and managers.</p>):group==='no_shows'?<NoShowReport key={props.tenant+'/'+props.property} {...props}/>:<OperationsReports key={props.tenant+'/'+props.property} {...props}/>}</>;

}

function OperationsReports({tenant,property,businessDate,types,rooms}:Props){

 const [initialStart]=useState(businessDate),[initialEnd]=useState(afterDays(businessDate,7));

 const [start,setStart]=useState(initialStart),[end,setEnd]=useState(initialEnd),[kind,setKind]=useState<ReportKind>('arrivals'),[data,setData]=useState<OperationalReport|null>(null),[loadedKey,setLoadedKey]=useState(''),[busy,setBusy]=useState(true),[error,setError]=useState('');

 const sequence=useRef(0),mounted=useRef(true),key=tenant+'/'+property+'/'+start+'/'+end;

 async function load(){const seq=++sequence.current;setBusy(true);setError('');setLoadedKey('');try{if(!/^\d{4}-\d{2}-\d{2}$/.test(start)||!/^\d{4}-\d{2}-\d{2}$/.test(end)||end<=start)throw Error('Choose a valid start date and an end date after it.');const result=await hotelRpc<OperationalReport>('operational_report',{p_tenant:tenant,p_property:property,p_start:start,p_end:end});if(mounted.current&&seq===sequence.current){setData(result);setLoadedKey(key)}}catch(e){if(mounted.current&&seq===sequence.current)setError(e instanceof Error?e.message:'Unable to load report.')}finally{if(mounted.current&&seq===sequence.current)setBusy(false)}}

 useEffect(()=>{mounted.current=true;const seq=++sequence.current;hotelRpc<OperationalReport>('operational_report',{p_tenant:tenant,p_property:property,p_start:initialStart,p_end:initialEnd}).then(result=>{if(mounted.current&&seq===sequence.current){setData(result);setLoadedKey(tenant+'/'+property+'/'+initialStart+'/'+initialEnd);setError('')}}).catch(e=>{if(mounted.current&&seq===sequence.current)setError(e instanceof Error?e.message:'Unable to load report.')}).finally(()=>{if(mounted.current&&seq===sequence.current)setBusy(false)});return()=>{mounted.current=false}},[tenant,property,initialStart,initialEnd]);

 const fresh=!!data&&loadedKey===key&&!busy&&!error;

 const table=fresh?operationalRows(data,kind,types,rooms):null;

 const title=reportKinds.find(([id])=>id===kind)![1];

 const definitionKey=({arrivals:'arrivals_departures',departures:'arrivals_departures',in_house:'in_house_housekeeping',housekeeping:'in_house_housekeeping',daily_occupancy:'occupancy',forecast:'booked_value',cancellations:'cancellations',booking_sources:'booking_sources',channel_performance:'channel_performance'} as const)[kind];

 const definition=(data?.definitions[definitionKey]??reportDefinitions[kind])+(kind==='cancellations'?' This cohort includes recorded no-shows; do not add the separate no-show report count.':'');

 const generated=data?new Intl.DateTimeFormat('en-US',{dateStyle:'medium',timeStyle:'short',timeZone:data.property.time_zone}).format(new Date(data.generated_at)):'';

 function exportCsv(){if(!fresh||!data||!table)return;try{const metadata:ReportCell[][]=[['iRatePilot PMS',title],['Property',data.property.name],['Time zone',data.property.time_zone],['Period start',data.period.start],['Period end (exclusive)',data.period.end],['Generated at',data.generated_at],['Operational calendar date',data.business_date],['Basis',definition]];if(kind==='forecast'){const f=data.booked_value_forecast;metadata.push(['Unknown amount reservations',f.unknown_amount_reservations],['Completeness',f.unknown_amount_reservations?'Totals incomplete':'All amounts known'],['Accommodation USD',reportMoney(f.accommodation_minor)],['Taxes USD',reportMoney(f.taxes_minor)],['Property fees USD',reportMoney(f.hotel_fees_minor)],['OTA fees USD',reportMoney(f.ota_fees_minor)],['Full stay booked total USD',reportMoney(f.total_minor)])}if(kind==='daily_occupancy')metadata.push(['Room-type nights missing capacity',data.summary.unconfigured_type_nights],['Configured unit-nights',data.summary.configured_unit_nights??null],['Physical unit-nights',data.summary.physical_unit_nights??null],['Closed unit-nights',data.summary.closed_unit_nights??null],['Shortfall unit-nights',data.summary.shortfall_unit_nights??null],['Capacity basis','Current configured selling ceiling and physical room inventory reduced by effective dated maintenance closures. Historical physical assignments are not reconstructed.']);if(kind==='cancellations')metadata.push(['Undated cancellations excluded',data.summary.undated_cancellations]);downloadReport(data.property.name+'-'+kind+'-'+data.period.start+'-'+data.period.end,[...metadata,[],table.headers,...table.rows])}catch(e){setError(e instanceof Error?e.message:'Unable to export report.')}}

 return <section className="card pilot-reports"><div className="pilot-report-controls"><div className="section-top"><div><h2>Operations &amp; booking reports</h2><p>Choose dates, load a snapshot, then export or print the selected report.</p></div><div className="pilot-actions"><button className="secondary" disabled={!fresh} onClick={exportCsv}><Download size={16}/>Export CSV</button><button className="secondary" disabled={!fresh} onClick={()=>window.print()}><Printer size={16}/>Print / save PDF</button></div></div><form className="pilot-report-filters" onSubmit={e=>{e.preventDefault();void load()}}><label className="field">Report<select value={kind} onChange={e=>setKind(e.target.value as ReportKind)}>{reportKinds.map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label><label className="field">From<input type="date" required value={start} disabled={busy} onChange={e=>setStart(e.target.value)}/></label><label className="field">Until (exclusive)<input type="date" required value={end} disabled={busy} onChange={e=>setEnd(e.target.value)}/></label><button className="primary" disabled={busy}>{busy?'Loading…':'Load reports'}</button></form>{error&&<div className="pilot-error" role="alert">{error}</div>}</div>

 {!fresh?<output className="pilot-empty">{busy?'Loading the selected property and dates…':'Load the selected dates to view or export a report.'}</output>:data&&table&&<div className="pilot-report-print"><div className="pilot-report-heading"><span className="pilot-eyebrow">{data.property.name}</span><h2>{title}</h2><p>{data.period.start} through {data.period.end} (end exclusive) · {data.property.time_zone}</p><small>Generated {generated} · {table.rows.length} records</small></div><p className="pilot-report-basis">{definition}</p>{kind==='booking_sources'&&<p className="pilot-report-footnote">Booked amounts are saved full-stay guest totals, split between active and cancelled scheduled arrivals. Unknown amounts have separate counts; shown values are known subtotals. No-shows are included in cancellations. This is not nightly earned revenue, money collected, processor settlement, channel commission or profit, and a saved source does not prove a connected channel.</p>}{kind==='channel_performance'&&<p className="pilot-report-footnote">This arrival-cohort estimate uses saved source labels, accommodation amounts (taxes and property fees excluded) and recorded OTA fees. Missing OTA fees or accommodation amounts make contribution unavailable. Direct bookings assume no OTA fee. It excludes processor costs, refunds, commissions not recorded on reservations, operating expenses and settlement; it is not profit. A source label does not prove a live channel connection.</p>}{kind==='forecast'&&<><div className="pilot-report-totals">{([['Accommodation',data.booked_value_forecast.accommodation_minor],['Taxes',data.booked_value_forecast.taxes_minor],['Property fees',data.booked_value_forecast.hotel_fees_minor],['OTA fees',data.booked_value_forecast.ota_fees_minor],['Full stay booked value',data.booked_value_forecast.total_minor]] as const).map(([label,value])=><div key={String(label)}><span>{label}</span><strong>{reportUsd(value)}</strong></div>)}</div>{data.booked_value_forecast.unknown_amount_reservations>0&&<p className="pilot-error">{data.booked_value_forecast.unknown_amount_reservations} reservations have unknown amounts; totals are incomplete.</p>}</>}{kind==='daily_occupancy'&&<div className="pilot-report-totals">{([['Configured unit-nights',data.summary.configured_unit_nights],['Physical unit-nights',data.summary.physical_unit_nights],['Closed unit-nights',data.summary.closed_unit_nights],['Shortfall unit-nights',data.summary.shortfall_unit_nights]] as const).map(([label,value])=><div key={label}><span>{label}</span><strong>{value??'Unavailable'}</strong></div>)}</div>}{kind==='daily_occupancy'&&data.summary.unconfigured_type_nights>0&&<p className="pilot-error">{data.summary.unconfigured_type_nights} room-type nights have no capacity configured. Occupancy percentages are unavailable where capacity is incomplete.</p>}{kind==='cancellations'&&data.summary.undated_cancellations>0&&<p>{data.summary.undated_cancellations} cancellations have no arrival date and are excluded from this date-filtered report.</p>}<div className="pilot-table-wrap"><table className="pilot-table"><caption className="sr-only">{title} for {data.property.name}, {data.period.start} to {data.period.end} exclusive</caption><thead><tr>{table.headers.map(header=><th scope="col" key={header}>{header}</th>)}</tr></thead><tbody>{table.rows.map((row,i)=><tr key={i}>{row.map((cell,j)=><td key={j}>{reportCellText(cell)}</td>)}</tr>)}</tbody></table>{!table.rows.length&&<p className="pilot-empty">No records match this report.</p>}</div><output className="pilot-report-footnote">Loaded snapshot · {table.rows.length} records. Refresh reports after making operational changes.</output></div>}

 </section>;

}




